/* Emit every scripted solution as Lean and compile the lot with core Lean (no Mathlib):
 *     node dev/grimoire/check_emitted.js
 * The generated file lands in scratch/lean/ (gitignored), next to the Grimoire/ modules the concrete
 * sorts need. This is the emit-and-verify check: what the game claims to produce really compiles. */
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const { G, SOL, solver } = require('./solutions.js');

const REPO = path.resolve(__dirname, '..', '..');
const LEAN = path.join(REPO, 'scratch', 'lean');
if (!fs.existsSync(LEAN)) fs.mkdirSync(LEAN, { recursive: true });

let parts = ['-- AUTO-GENERATED by check_emitted.js — every exercise solved and emitted, compiled by core Lean.\n'], missing = [];
const heads = [], opens = [];   // `import` must head the FILE, so concrete sorts' modules are hoisted here
G.EXERCISES.forEach(ex => {
  if (!SOL[ex.id]) { missing.push(ex.id); return; }
  const s = solver(ex.id); SOL[ex.id](s);
  if (s.env.parent) throw new Error(ex.id + ' did not return to root');
  if (!s.env.bindings.some(b => G.exprEq(b.type, s.env.goal))) throw new Error(ex.id + ' not solved');
  G.leanImports(ex).forEach(i => { if (!heads.includes(i.imp)) heads.push(i.imp); if (i.open && !opens.includes(i.open)) opens.push(i.open); });
  parts.push('-- ' + ex.id + (ex.leanName ? '  (' + ex.leanName + ')' : '') + '\nsection\n' + G.leanPreamble(ex) + G.emitLean(ex, s.env) + '\nend\n');
  // solving a lemma mints its recipe (as in the game), so later exercises can REUSE it via matching
  if (ex.kind === 'lemma' && ex.leanName && !G.RECIPES[ex.leanName]) G.RECIPES[ex.leanName] = G.recipeFromExercise(ex);
});
if (missing.length) console.log('(no solution scripted for: ' + missing.join(', ') + ')');
const gen = path.join(LEAN, 'grimoire_generated.lean');
fs.writeFileSync(gen, heads.concat(opens).join('\n') + (heads.length ? '\n\n' : '') + parts.join('\n'));
console.log('wrote ' + (parts.length - 1) + ' proofs → ' + gen);
const env = Object.assign({}, process.env, { LEAN_PATH: LEAN });
try {
  // A concrete sort (Nat) lives in a real Lean module, committed beside this script. Build its .olean
  // into scratch/lean/Grimoire/ — LEAN_PATH points there — so no build artifact lands in the repo.
  const SRCDIR = path.join(__dirname, 'Grimoire'), OUTDIR = path.join(LEAN, 'Grimoire');
  if (!fs.existsSync(OUTDIR)) fs.mkdirSync(OUTDIR, { recursive: true });
  fs.readdirSync(SRCDIR).filter(f => f.endsWith('.lean')).forEach(f => {
    // `lean` insists the input sit under its root directory, so compile from dev/grimoire/ and send the
    // .olean over to scratch/lean/Grimoire/, which is where LEAN_PATH looks for it.
    const out = path.join(OUTDIR, f.replace(/\.lean$/, '.olean'));
    execSync('lean -o ' + JSON.stringify(out) + ' ' + JSON.stringify(path.join('Grimoire', f)), { cwd: __dirname, stdio: 'pipe' });
  });
  execSync('lean ' + JSON.stringify(gen), { cwd: LEAN, stdio: 'pipe', env: env });
  console.log('✓ all emitted proofs compile with core Lean (exit 0)');
} catch (e) {
  console.log('✗ Lean reported errors:\n' + (e.stdout ? e.stdout.toString() : '') + (e.stderr ? e.stderr.toString() : ''));
  process.exit(1);
}
